import { Component } from '@angular/core';

@Component({
  selector: 'app-data-manipulation',
  templateUrl: './data-manipulation.component.html',
  styleUrls: ['./data-manipulation.component.css']
})
export class DataManipulationComponent {

  tableOfContents: Array<string>[]= [
    ['section1','Abstract'],
    ['section2','Unify duplicates registers'],
    ['section3','Regex: Cleaning Phone Numbers'],
    ['section4','Unify two dataframes']    
  ];

  sections: Array<string>[]=[
    []
  ]

  ngOnInit() {      
    this.loadScript('./assets/prism.js', 'js');
    window.onload = () => {
      this.loadScript('./assets/main.js', 'js');
    };
  }

  loadScript(scriptUrl: string,Tipo: string) {
    if (Tipo=='js'){
      const script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = scriptUrl;
      document.body.appendChild(script);
    }  else if (Tipo === 'css') {
      const link = document.createElement('link');
      link.rel='stylesheet'
      link.type = 'text/css';
      link.href = scriptUrl;
      document.head.appendChild(link);
    }   
  }

  scrollToSection(elementId: string): void {
    const elementToScrollTo = document.getElementById(elementId);
    if (elementToScrollTo) {
      elementToScrollTo.scrollIntoView({ behavior: 'smooth' });
    }
  }

}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Document</title>
</head>
<body>

    <app-header></app-header>

    <div class="global">
        <div class="toc">
            <app-table-of-contents [tableOfContents]="tableOfContents"
                (scrollToElement)="scrollToSection($event)"></app-table-of-contents>
        </div>

        <div class="content">
            <div id="section1">
                <h2>Abstract</h2>
                <p>
                    Here i'll share you a list of problems about data cleaning and manipulations, that i consider
                    goods and needs a high level of skill to handle data, and the best way to solve it by me.
                </p>
                <p>
                    I'll use pyspark and python native fuction to solve the problems.
                </p>
            </div>

            <div class="section2">
                <h2>Unify duplicates registers</h2>
                 The first problem take a dataframe
                <p></p>
            </div>
        </div>  
    </div>
</body>
</html>
